// -------------------------------------------------------
// CONFIGURATION
// -------------------------------------------------------

// The first order number that will be issued.
// Change this before your first order if needed.
define( 'TITAN_ORDER_SEQ_START', 10051000 );

// Internal WordPress option name used to store the counter.
// No need to change this.
define( 'TITAN_ORDER_SEQ_OPTION', 'titan_order_sequence' );


// -------------------------------------------------------
// Assign sequential number at checkout
// Hooks into both classic checkout and block-based checkout
// -------------------------------------------------------
add_action( 'woocommerce_checkout_order_created',             'titan_assign_order_sequence' );
add_action( 'woocommerce_store_api_checkout_order_processed', 'titan_assign_order_sequence' );

function titan_assign_order_sequence( $order ) {

    // Bail if a number is already stored — prevents duplicates if the hook fires twice.
    if ( $order->get_meta( '_titan_order_sequence' ) ) {
        return;
    }

    global $wpdb;

    // Create the counter in the database the very first time (does nothing on subsequent orders).
    add_option( TITAN_ORDER_SEQ_OPTION, TITAN_ORDER_SEQ_START - 1, '', 'no' );

    // Atomically increment the counter — safe when two orders arrive at the same moment.
    $wpdb->query(
        $wpdb->prepare(
            "UPDATE {$wpdb->options} SET option_value = LAST_INSERT_ID(option_value + 1) WHERE option_name = %s",
            TITAN_ORDER_SEQ_OPTION
        )
    );

    // Read back the number this order was assigned.
    $sequence = (int) $wpdb->get_var( 'SELECT LAST_INSERT_ID()' );

    // Store it on the order so it never changes.
    $order->update_meta_data( '_titan_order_sequence', $sequence );
    $order->save_meta_data();
}


// -------------------------------------------------------
// Display the order number in Sellerdeck format
// Fires on: thank-you page, My Account, admin orders, emails
// Format: {INITIALS}{POSTCODE_DIGITS}{SEQUENCE}
// Example: DL86QL10051000
// -------------------------------------------------------
add_filter( 'woocommerce_order_number', 'titan_sellerdeck_order_number', 10, 2 );

function titan_sellerdeck_order_number( $order_id, $order ) {

    // --- Initials: first letter of billing first name + last name ---
    $first    = strtoupper( (string) $order->get_billing_first_name() );
    $last     = strtoupper( (string) $order->get_billing_last_name() );
    $initials = ( $first ? $first[0] : 'X' ) . ( $last ? $last[0] : 'X' );

    // --- Postcode: strip leading area letters ---
    // NG8 6QL → remove space → NG86QL → strip leading letters → 86QL
    $postcode      = strtoupper( str_replace( ' ', '', (string) $order->get_billing_postcode() ) );
    $postcode_part = preg_replace( '/^[A-Z]+/', '', $postcode ) ?: $postcode;

    // --- Sequential number stored on the order at creation ---
    // Falls back to zero-padded post ID for orders placed before this snippet was active.
    $sequence = $order->get_meta( '_titan_order_sequence' )
        ?: str_pad( (string) $order_id, 8, '0', STR_PAD_LEFT );

    return $initials . $postcode_part . $sequence;
}
